//! Text dumps for tests: ordered `key = value` lines compared exactly with a file, so a change in
//! generated styles or tokens shows up as a reviewable diff.
//!
//! Without `UPDATE_DUMPS`, a mismatch fails with the differing lines; with `UPDATE_DUMPS=1` the
//! file is rewritten. Dumps are generated by tests only, never edited by hand.
//!
//! ```no_run
//! use craft_ui::testing::dump::Dump;
//!
//! let mut dump = Dump::new();
//! dump.line("button.height", 24.0).line("button.fill", egui::Color32::from_rgb(0x26, 0x26, 0x2a));
//! dump.group("button.border", |d| {
//!     d.line("width", 1.0);
//! });
//! dump.check(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/dumps/components/button.txt"));
//! ```

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::Path;

use egui::{Color32, CornerRadius, FontFamily, FontId, Margin, Rangef, Shadow, Stroke, Vec2};

/// Ordered `key = value` lines.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Dump {
    text: String,
    prefix: String,
}

impl Dump {
    pub fn new() -> Self {
        Self::default()
    }

    /// A `# text` line, e.g. naming the test that writes the file.
    pub fn comment(&mut self, text: &str) -> &mut Self {
        let _ = writeln!(self.text, "# {text}");
        self
    }

    /// Appends `key = value`, with `key` under the current [`group`](Self::group) prefix.
    pub fn line(&mut self, key: &str, value: impl DumpValue) -> &mut Self {
        let _ = writeln!(self.text, "{}{key} = {}", self.prefix, value.dump_value());
        self
    }

    /// Runs `f` with `prefix.` put before every key it writes.
    pub fn group(&mut self, prefix: &str, f: impl FnOnce(&mut Dump)) -> &mut Self {
        let len = self.prefix.len();
        let _ = write!(self.prefix, "{prefix}.");
        f(self);
        self.prefix.truncate(len);
        self
    }

    /// The lines written so far.
    pub fn text(&self) -> &str {
        &self.text
    }

    /// The `(key, value)` pairs written so far, keys with their group prefixes; comments are
    /// skipped.
    pub fn entries(&self) -> impl Iterator<Item = (String, &str)> {
        self.text.lines().filter(|line| !line.starts_with('#')).filter_map(|line| line.split_once(" = ")).map(|(key, value)| (key.to_owned(), value))
    }

    /// Compares with the file at `path`, or rewrites it when [`update_requested`]. The error
    /// names the file and lists the differing lines.
    pub fn compare(&self, path: impl AsRef<Path>) -> Result<(), String> {
        let path = path.as_ref();
        let old = std::fs::read_to_string(path);
        if update_requested() {
            if old.as_deref().ok() == Some(self.text.as_str()) {
                return Ok(());
            }
            if let Some(dir) = path.parent() {
                std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
            }
            return std::fs::write(path, &self.text).map_err(|e| format!("{}: {e}", path.display()));
        }
        match old {
            Ok(old) if old == self.text => Ok(()),
            Ok(old) => Err(format!("{} differs:\n{}", path.display(), diff(&old, &self.text))),
            Err(e) => Err(format!("{}: {e}", path.display())),
        }
    }

    /// [`compare`](Self::compare), failing the test on a mismatch.
    #[track_caller]
    #[allow(clippy::panic)] // a test assertion
    pub fn check(&self, path: impl AsRef<Path>) {
        if let Err(message) = self.compare(path) {
            panic!("{message}\nRerun with UPDATE_DUMPS=1 to rewrite the dump, then review the diff.");
        }
    }
}

/// Checks a directory one test owns: every `(file name, dump)` pair, and no other `.txt` files
/// (with `UPDATE_DUMPS=1` they are removed). Fails with the first three diffs.
#[track_caller]
#[allow(clippy::panic)] // a test assertion
pub fn check_dir(dir: impl AsRef<Path>, dumps: &[(String, Dump)]) {
    let dir = dir.as_ref();
    let names: BTreeSet<&str> = dumps.iter().map(|(name, _)| name.as_str()).collect();
    let stale: Vec<_> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|p| p.extension().is_some_and(|e| e == "txt"))
        .filter(|p| p.file_name().and_then(|n| n.to_str()).is_some_and(|n| !names.contains(n)))
        .collect();

    let mut errors: Vec<String> = dumps.iter().filter_map(|(name, dump)| dump.compare(dir.join(name)).err()).collect();
    for path in stale {
        if update_requested() {
            if let Err(e) = std::fs::remove_file(&path) {
                errors.push(format!("{}: {e}", path.display()));
            }
        } else {
            errors.push(format!("{}: no longer generated", path.display()));
        }
    }
    if !errors.is_empty() {
        let shown: Vec<&str> = errors.iter().take(3).map(String::as_str).collect();
        panic!("{} dump file(s) differ; rerun with UPDATE_DUMPS=1 to rewrite them, then review the diff\n{}", errors.len(), shown.join("\n"));
    }
}

/// Whether `UPDATE_DUMPS` is set (to anything but `0`).
pub fn update_requested() -> bool {
    std::env::var_os("UPDATE_DUMPS").is_some_and(|v| v != "0")
}

/// The lines only in `old` (`- `) and only in `new` (`+ `), at most 20. Dump keys are unique, so
/// this reads as a diff.
pub fn diff(old: &str, new: &str) -> String {
    const MAX: usize = 20;
    let (a, b): (BTreeSet<&str>, BTreeSet<&str>) = (old.lines().collect(), new.lines().collect());
    let removed = old.lines().filter(|l| !b.contains(l)).map(|l| format!("- {l}"));
    let added = new.lines().filter(|l| !a.contains(l)).map(|l| format!("+ {l}"));
    let all: Vec<String> = removed.chain(added).collect();
    let mut out: Vec<String> = all.iter().take(MAX).cloned().collect();
    if all.len() > MAX {
        out.push(format!("… {} more", all.len() - MAX));
    }
    out.join("\n")
}

/// A value's text in a dump.
pub trait DumpValue {
    fn dump_value(&self) -> String;
}

impl<T: DumpValue + ?Sized> DumpValue for &T {
    fn dump_value(&self) -> String {
        (**self).dump_value()
    }
}

/// Up to two decimals, trailing zeros dropped: `12`, `10.5`, `0.33`.
impl DumpValue for f32 {
    fn dump_value(&self) -> String {
        let s = format!("{self:.2}");
        let s = s.trim_end_matches('0').trim_end_matches('.');
        if s == "-0" { "0".to_owned() } else { s.to_owned() }
    }
}

macro_rules! display_values {
    ($($t:ty),*) => { $(impl DumpValue for $t { fn dump_value(&self) -> String { self.to_string() } })* };
}
display_values!(bool, u8, u16, u32, u64, usize, i8, i16, i32, i64, str, String);

/// `none`, or the value.
impl<T: DumpValue> DumpValue for Option<T> {
    fn dump_value(&self) -> String {
        self.as_ref().map_or_else(|| "none".to_owned(), DumpValue::dump_value)
    }
}

/// `#rrggbbaa`, unmultiplied.
impl DumpValue for Color32 {
    fn dump_value(&self) -> String {
        let [r, g, b, a] = self.to_srgba_unmultiplied();
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    }
}

/// `#rrggbbaa`.
impl DumpValue for craft_theme::Rgba {
    fn dump_value(&self) -> String {
        let [r, g, b, a] = self.0;
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    }
}

/// `x y`.
impl DumpValue for Vec2 {
    fn dump_value(&self) -> String {
        format!("{} {}", self.x.dump_value(), self.y.dump_value())
    }
}

/// `min..max`.
impl DumpValue for Rangef {
    fn dump_value(&self) -> String {
        format!("{}..{}", self.min.dump_value(), self.max.dump_value())
    }
}

/// `width colour`.
impl DumpValue for Stroke {
    fn dump_value(&self) -> String {
        format!("{} {}", self.width.dump_value(), self.color.dump_value())
    }
}

/// One number when all corners match, else `nw ne sw se`.
impl DumpValue for CornerRadius {
    fn dump_value(&self) -> String {
        let CornerRadius { nw, ne, sw, se } = *self;
        if nw == ne && ne == sw && sw == se { nw.to_string() } else { format!("{nw} {ne} {sw} {se}") }
    }
}

/// One number when all sides match, else `left right top bottom`.
impl DumpValue for Margin {
    fn dump_value(&self) -> String {
        let Margin { left, right, top, bottom } = *self;
        if left == right && right == top && top == bottom { left.to_string() } else { format!("{left} {right} {top} {bottom}") }
    }
}

/// `offset x y, blur b, spread s, colour`.
impl DumpValue for Shadow {
    fn dump_value(&self) -> String {
        let Shadow { offset: [x, y], blur, spread, color } = *self;
        format!("offset {x} {y}, blur {blur}, spread {spread}, {}", color.dump_value())
    }
}

/// `proportional`, `monospace` or the family's name.
impl DumpValue for FontFamily {
    fn dump_value(&self) -> String {
        match self {
            FontFamily::Proportional => "proportional".to_owned(),
            FontFamily::Monospace => "monospace".to_owned(),
            FontFamily::Name(name) => name.to_string(),
        }
    }
}

/// `size family`.
impl DumpValue for FontId {
    fn dump_value(&self) -> String {
        format!("{} {}", self.size.dump_value(), self.family.dump_value())
    }
}

/// Every built-in theme in each mode it has, at the Compact size and standard contrast, as
/// (`<theme>.<mode>`, tokens): the appearances component dumps are written for.
pub fn appearances() -> Vec<(String, crate::theme::UiTokens)> {
    use craft_theme::{Appearance, Contrast, Mode, Size, TextSize, Variants, builtins, resolve};

    let mut out = Vec::new();
    for theme in builtins() {
        let modes = match theme.variants {
            Variants::Both => &[Mode::Light, Mode::Dark][..],
            Variants::LightOnly => &[Mode::Light],
            Variants::DarkOnly => &[Mode::Dark],
        };
        for &mode in modes {
            let appearance =
                Appearance { mode, contrast: Contrast::Standard, size: Size::Compact, text_size: TextSize::default(), reduced_motion: false };
            let tokens = resolve(theme, appearance, None).tokens;
            let id = theme.id.as_str();
            let name = id.strip_prefix("craft.").unwrap_or(id);
            let mode_name = if mode == Mode::Light { "light" } else { "dark" };
            out.push((format!("{name}.{mode_name}"), crate::theme::UiTokens::new(tokens, appearance, mode, crate::theme::FontFamilies::default())));
        }
    }
    out
}

/// A component dump at `path`: a `header` comment, then `each` once per [`appearances`] entry in a
/// group of its name.
#[track_caller]
pub fn check_component(path: impl AsRef<Path>, header: &str, mut each: impl FnMut(&mut Dump, &crate::theme::UiTokens)) {
    let mut dump = Dump::new();
    dump.comment(header);
    for (name, tokens) in appearances() {
        dump.group(&name, |d| each(d, &tokens));
    }
    dump.check(path);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dump_writes_grouped_lines_and_diffs_by_line() {
        let mut dump = Dump::new();
        dump.comment("header").line("a", 1.5f32).group("b", |d| {
            d.line("c", Color32::from_rgb(1, 2, 3)).group("d", |d| {
                d.line("e", -0.001f32);
            });
        });
        dump.line("f", Some(Vec2::new(2.0, 0.126)));
        assert_eq!(dump.text(), "# header\na = 1.5\nb.c = #010203ff\nb.d.e = 0\nf = 2 0.13\n");
        assert_eq!(diff("a = 1\nb = 2\n", "a = 1\nb = 3\n"), "- b = 2\n+ b = 3");
    }
}
